use moloch_live_runtime::owned_age_reads::{Scheduler,RESAMPLE_MS};
use moloch_replay::session::Session;
use baal_transport_service::Scope;
use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{collections::BTreeSet,path::PathBuf,sync::atomic::{AtomicU64,Ordering}};
const BASE:u64=1_792_054_800_000;
fn iso(t:u64)->String{chrono::DateTime::from_timestamp_millis((BASE+t)as i64).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true)}
fn hash(v:&Value)->String{format!("{:x}",Sha256::digest(serde_json::to_vec(v).unwrap()))}
struct F{bank:Session,scope:Scope,root:PathBuf}
impl Drop for F{fn drop(&mut self){let _=std::fs::remove_dir_all(&self.root);}}
impl F{
 fn new()->Self{static N:AtomicU64=AtomicU64::new(0);let root=std::env::temp_dir().join(format!("owned-age-{}-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos(),N.fetch_add(1,Ordering::Relaxed)));let policy=json!({"initialCash":"100.000000","maximumCommitted":"40.000000","maximumMarketCost":"10.000000","quantity":10,"maximumMarkets":4,"entryStopAt":iso(600000),"requireCurrentFlow":true,"minimumSpreadTicks":1000,"maximumInventoryAgeMs":60000,"inventoryAgeClock":"execution","inventoryExitMode":"fixedGain","inventoryExitDepthBps":5000});let seed=json!({"runId":"age-fixture","tournamentId":"cup","availableCash":"100.000000","accountSnapshotHash":"a".repeat(64),"observedAt":iso(0)});let bank=Session::open_live(&root,&policy,&seed).unwrap();let scope=Scope{tournament_id:"cup".into(),tournament_slug:"cup".into(),exchanges:(101..=104).map(|n|(n.to_string(),n.to_string())).collect()};Self{bank,scope,root}}
 fn put(&mut self,e:&Value){let seq=self.bank.last_source_sequence("fixture")+1;self.bank.accept("fixture",seq,e).unwrap();}
 fn book(&mut self,ex:&str,at:u64){self.put(&json!({"type":"book","receivedAt":iso(at),"book":{"marketId":ex,"exchangeId":ex,"tournamentId":"cup","sequence":(at+1).to_string(),"sourceAt":iso(at),"requestStartedAt":iso(at),"receivedAt":iso(at),"bids":[{"price":"0.400000","quantity":100}],"asks":[{"price":"0.450000","quantity":100}]}}));}
 fn buy(&mut self,ex:&str,at:u64,n:u64){self.book(ex,at);let raw=self.bank.engine().live_package_books().into_iter().find(|b|b["exchangeId"]==ex).unwrap();let event=json!({"type":"reviewed_fundamental_entry_reserved_v1","source":"moloch_live_dispatcher","bankScope":{"runId":"age-fixture","bankManifestHash":self.bank.manifest_hash(),"tournamentId":"cup"},"bankHead":self.bank.durable_head(),"expectedReportSha256":hash(&self.bank.engine().report().unwrap()),"originSha256":"a".repeat(64),"reviewSha256":"b".repeat(64),"bookSha256":hash(&raw),"reviewCurrentUntilMs":BASE+600000,"marketId":ex,"exchangeId":ex,"side":"YES","limitPrice":"0.400000","expectedPayout":"0.600000","marginPerShare":"0.010000","reviewMaximumQuantity":5,"reviewMaximumPrincipal":"10.000000","expiresAt":iso(at+60000),"receivedAt":iso(at),"processedAt":iso(at)});self.put(&event);let q=self.bank.engine().order_records().into_iter().find(|q|q["exchangeId"]==ex&&q["action"]=="buy"&&q["retired"]==false).unwrap();let mut e=json!({"type":"actual_order_ack","source":"official_sig_api_v1","receiptHash":"c".repeat(64),"orderId":q["id"],"actualOrderId":format!("9{}",q["id"]),"exchangeId":ex,"marketId":ex,"side":"YES","action":"buy","price":"0.400000","quantity":q["quantity"],"receivedAt":iso(at+3000)});self.put(&e);e["type"]=json!("actual_fill");e["quantity"]=json!(n);e["fillId"]=json!(format!("8{}",q["id"]));e["fee"]=json!("0.000000");e["executedAt"]=json!(iso(at+3000));e["processedAt"]=json!(iso(at+4000));e["receivedAt"]=json!(iso(at+4000));self.put(&e);for old in self.bank.engine().order_records().into_iter().filter(|q|q["action"]=="sell"&&q["retired"]==false){self.put(&json!({"type":"unsubmitted_intent_retired","source":"moloch_live_dispatcher","orderId":old["id"],"confirmedNetworkAttempts":0,"receiptHash":"d".repeat(64),"deferPlanningForPackage":true,"receivedAt":iso(at+4000)}));}}
 fn nominate(&self,s:&mut Scheduler,current:&str,at:u64)->Option<moloch_live_runtime::owned_age_reads::ReadHint>{s.nominate(&self.bank,&self.scope,&BTreeSet::new(),current,BASE+at).unwrap()}
}
#[test]fn due_actual_partial_fill_needs_no_prior_maxage_sell_and_uses_execution_not_reconcile_clock(){let mut f=F::new();f.buy("101",0,2);assert!(!f.bank.engine().order_records().iter().any(|q|q["inventoryExitReason"]=="maximumAge"));let before=f.bank.engine().report().unwrap();let mut s=Scheduler::new(&f.scope).unwrap();assert!(f.nominate(&mut s,"102",62999).is_none());let h=f.nominate(&mut s,"102",63000).unwrap();assert_eq!(h.exchange_id(),"101");assert_eq!(h.market_id(),"101");assert_eq!(h.oldest_execution_ms(),BASE+3000);assert_eq!(h.due_at_ms(),BASE+63000);assert_eq!(h.native_head(),&f.bank.durable_head());assert_eq!(f.bank.engine().report().unwrap(),before);}
#[test]fn current_scope_and_reviewed_managed_hold_are_not_preempted(){let mut f=F::new();f.buy("101",0,5);let mut s=Scheduler::new(&f.scope).unwrap();assert!(f.nominate(&mut s,"101",63000).is_none());assert!(s.nominate(&f.bank,&f.scope,&["101".into()].into(),"102",BASE+64000).unwrap().is_none());}
#[test]fn actual_completed_ordinary_read_starts_same_thirty_second_cooldown(){let mut f=F::new();f.buy("101",0,5);let mut s=Scheduler::new(&f.scope).unwrap();s.record_source_read("101",BASE+63000,BASE+64000).unwrap();assert!(f.nominate(&mut s,"102",93999).is_none());assert_eq!(f.nominate(&mut s,"102",94000).unwrap().exchange_id(),"101");}
#[test]fn completion_requires_issued_hint_and_actual_interval_and_never_runs_on_nomination_alone(){let mut f=F::new();f.buy("101",0,5);let mut s=Scheduler::new(&f.scope).unwrap();let h=f.nominate(&mut s,"102",63000).unwrap();assert!(s.complete_read(&h,BASE+62999,BASE+64000).is_err());assert!(f.nominate(&mut s,"102",63001).is_none());let newer=f.nominate(&mut s,"102",63002).unwrap();assert!(s.complete_read(&h,BASE+63003,BASE+64000).is_err());s.complete_read(&newer,BASE+63003,BASE+64000).unwrap();assert!(s.complete_read(&newer,BASE+64001,BASE+64002).is_err());assert!(f.nominate(&mut s,"102",64001).is_none());assert!(f.nominate(&mut s,"102",94000).is_some());}
#[test]fn overdue_markets_roundrobin_and_regular_iteration_alternates(){let mut f=F::new();f.buy("101",0,5);f.buy("102",20000,5);let mut s=Scheduler::new(&f.scope).unwrap();assert_eq!(f.nominate(&mut s,"104",90000).unwrap().exchange_id(),"101");assert!(f.nominate(&mut s,"104",90001).is_none());assert_eq!(f.nominate(&mut s,"104",90002).unwrap().exchange_id(),"102");assert!(f.nominate(&mut s,"104",90003).is_none());assert_eq!(f.nominate(&mut s,"104",90004).unwrap().exchange_id(),"101");}
#[test]fn inherited_only_lot_without_actual_execution_is_not_a_new_loss_timer(){let mut f=F::new();f.put(&json!({"type":"actual_position_adoption","source":"official_sig_api_v1","authority":"human_moloch_inherited_management_20261015","complete":true,"receiptHash":"d".repeat(64),"tournamentId":"cup","receivedAt":iso(0),"requestStartedAt":iso(0),"openingCost":"1.000000","effectiveMaximumMarkets":5,"positions":[{"marketId":"101","exchangeId":"101","quantity":5,"lotPrincipal":"1.000000","reportedCostBasis":"1.000000","reportedMinusLotPrincipal":"0.000000","basisClassification":"exact","lots":[{"lotId":"901","quantity":5,"side":"YES","entryPrice":"0.200000","openedAt":iso(0)}]}]}));let mut s=Scheduler::new(&f.scope).unwrap();assert!(f.nominate(&mut s,"102",120000).is_none());}
#[test]fn stale_gap_and_tiny_depth_cannot_manufacture_a_sell_via_read_hint(){let mut f=F::new();f.buy("101",0,5);f.put(&json!({"type":"gap","exchangeId":"101","receivedAt":iso(10000)}));let before=f.bank.engine().report().unwrap();let mut s=Scheduler::new(&f.scope).unwrap();assert!(f.nominate(&mut s,"102",63000).is_some());assert_eq!(f.bank.engine().report().unwrap(),before);assert_eq!(f.bank.engine().wallet.quantity("101",moloch_replay::Side::Yes),5);}
#[test]fn current_scope_foreign_managed_changed_scope_and_clock_regression_deny(){let mut f=F::new();f.buy("101",0,5);let mut s=Scheduler::new(&f.scope).unwrap();assert!(s.nominate(&f.bank,&f.scope,&BTreeSet::new(),"999",BASE+63000).is_err());assert!(s.nominate(&f.bank,&f.scope,&["999".into()].into(),"102",BASE+63000).is_err());let mut changed=f.scope.clone();changed.exchanges.insert("101".into(),"999".into());assert!(s.nominate(&f.bank,&changed,&BTreeSet::new(),"102",BASE+63000).is_err());assert!(f.nominate(&mut s,"102",63000).is_some());assert!(s.nominate(&f.bank,&f.scope,&BTreeSet::new(),"102",BASE+62999).is_err());assert!(s.record_source_read("999",BASE+64000,BASE+65000).is_err());assert!(s.record_source_read("101",BASE+65000,BASE+64000).is_err());}
#[test]fn no_owned_positions_and_future_execution_relative_to_now_are_not_due(){let mut f=F::new();let mut s=Scheduler::new(&f.scope).unwrap();assert!(f.nominate(&mut s,"102",0).is_none());f.buy("101",0,5);let mut s=Scheduler::new(&f.scope).unwrap();assert!(s.nominate(&f.bank,&f.scope,&BTreeSet::new(),"102",BASE+2999).is_err());assert_eq!(RESAMPLE_MS,30000);}
#[test]fn actual_partial_package_inventory_stays_protected_from_ordinary_age_reads(){let mut f=F::new();f.book("101",0);f.book("102",0);let hashes=f.bank.engine().live_package_books().into_iter().map(|b|(b["exchangeId"].as_str().unwrap().to_owned(),hash(&b))).collect::<std::collections::BTreeMap<_,_>>();let scope=json!({"runId":"age-fixture","bankManifestHash":f.bank.manifest_hash(),"tournamentId":"cup"});f.put(&json!({"type":"live_package_reserve","source":"moloch_live_dispatcher","receivedAt":iso(1),"processedAt":iso(1),"packageId":"protected","proofHash":"a".repeat(64),"bankScope":scope,"expiresAt":iso(9000),"economics":{"maximumCost":"4.500000","minimumPayout":"5.000000","minimumSurplus":"0.500000","feeTotal":"0.000000"},"legs":[{"marketId":"101","exchangeId":"101","side":"YES","quantity":5,"limitPrice":"0.450000","bookHash":hashes["101"]},{"marketId":"102","exchangeId":"102","side":"YES","quantity":5,"limitPrice":"0.450000","bookHash":hashes["102"]}]}));f.put(&json!({"type":"live_package_attempt","source":"moloch_live_dispatcher","receivedAt":iso(3001),"processedAt":iso(3001),"packageId":"protected","proofHash":"a".repeat(64),"bankScope":scope,"requestHash":"b".repeat(64),"idempotencyKey":"age-protected","bookHashes":hashes}));let q=f.bank.engine().order_records().into_iter().find(|q|q["exchangeId"]=="101").unwrap();let mut actual=json!({"type":"actual_order_ack","source":"official_sig_api_v1","receiptHash":"c".repeat(64),"orderId":q["id"],"actualOrderId":"901","exchangeId":"101","marketId":"101","side":"YES","action":"buy","quantity":5,"price":"0.450000","receivedAt":iso(3001)});f.put(&actual);actual["type"]=json!("actual_fill");actual["quantity"]=json!(2);actual["fillId"]=json!("801");actual["fee"]=json!("0.000000");actual["executedAt"]=json!(iso(3001));f.put(&actual);assert_eq!(f.bank.engine().wallet.quantity("101",moloch_replay::Side::Yes),2);let mut scheduler=Scheduler::new(&f.scope).unwrap();assert!(f.nominate(&mut scheduler,"104",100000).is_none());assert!(f.bank.engine().package_blocks_submissions());}
